-- rule kernel: GroupByOrder (sqlite)
WITH cte1 AS (SELECT DISTINCT 7 AS c0 FROM tp AS a1 ORDER BY 1) SELECT CAST('ß' AS TEXT) AS c0, CAST(10.0 AS REAL) AS c1, '{"k": -1, "a": [1, 2, 3]}' AS c2 UNION SELECT a2.c1 AS c0, CASE WHEN FALSE THEN CAST(10.0 AS REAL) ELSE CAST(1.0 AS REAL) END AS c1, (SELECT JSON_GROUP_ARRAY (7 ORDER BY 7) FROM cte1 AS a3 WHERE FALSE) AS c2 FROM tl AS a2 WHERE ('{"k": 1, "a": [1, 2]}' = '{}');
